package dev.pocketengine.features.local.project;

import dev.pocketengine.features.local.NativeCommandExecutor;
import dev.pocketengine.features.workspace.VersionedWorkspace;
import java.io.File;
import java.nio.file.*;
import java.nio.file.attribute.BasicFileAttributes;
import java.util.*;
import org.json.*;

/** A native directory-state pin in the original patch plan, not an empty-file alias or grant. */
public final class ProjectDirectoryCreate {
    public static final String CONTRACT="pocketworld.exact-source-directory-create.v1";public static final int MAX_DEPTH=40;
    private ProjectDirectoryCreate(){}
    private static Set<String> keys(JSONObject value){Set<String> out=new TreeSet<>();value.keys().forEachRemaining(out::add);return out;}
    public static boolean matches(JSONObject row){return CONTRACT.equals(row.optString("directoryContract"));}
    public static boolean any(JSONArray rows)throws Exception{for(int i=0;i<rows.length();i++)if(matches(rows.getJSONObject(i)))return true;return false;}
    private static String path(String value){String path=VersionedWorkspace.path(value);if(!ProjectSources.sourcePath(path)||path.split("/").length>MAX_DEPTH)throw new IllegalArgumentException("目录仅支持原source范围及40层以内路径，不含依赖/构建根");return path;}
    private static File resolve(File root,String relative)throws Exception{File file=relative.isEmpty()?root:NativeCommandExecutor.within(root,relative);if(!file.getAbsoluteFile().equals(file.getCanonicalFile()))throw new SecurityException("目录路径不能包含链接");return file;}
    private static String identity(File root,String relative,ProjectFileQueries.Current current)throws Exception{
        current.check();File file=resolve(root,relative);BasicFileAttributes attrs;try{attrs=Files.readAttributes(file.toPath(),BasicFileAttributes.class,LinkOption.NOFOLLOW_LINKS);}catch(NoSuchFileException absent){return "absent";}
        if(!attrs.isDirectory()||attrs.isSymbolicLink())throw new SecurityException("同名路径不是普通目录，未覆盖文件/链接/特殊项");return ProjectSources.digest(new JSONObject().put("contract",CONTRACT).put("path",relative).put("key",String.valueOf(attrs.fileKey())).put("modified",attrs.lastModifiedTime().toString()).put("created",attrs.creationTime().toString()));
    }
    public static JSONArray prepare(File root,JSONObject edit,ProjectFileQueries.Current current)throws Exception{
        Set<String> names=keys(edit);if(!Set.of("action","path","createParents").containsAll(names)||!names.containsAll(Set.of("action","path"))||!"mkdir".equals(edit.optString("action"))||edit.has("createParents")&&!(edit.opt("createParents")instanceof Boolean))throw new IllegalArgumentException("mkdir只接收path和明确createParents，不接受正文/文件SHA/权限或任意路径");
        String target=path(edit.getString("path"));boolean parents=edit.optBoolean("createParents");String anchor="",anchorIdentity=identity(root,"",current),part="";if("absent".equals(anchorIdentity))throw new SecurityException("原工作副本根不存在");JSONArray missing=new JSONArray();
        for(String name:target.split("/")){part=part.isEmpty()?name:part+"/"+name;String actual=identity(root,part,current);if("absent".equals(actual))missing.put(part);else{if(missing.length()>0)throw new SecurityException("目录祖先状态不一致，未生成跨版本方案");anchor=part;anchorIdentity=actual;}}
        if(!parents&&missing.length()>1)throw new IllegalArgumentException("父目录不存在；createParents缺省false，未隐式递归建目录");
        JSONObject descriptor=new JSONObject().put("path",target).put("createParents",parents).put("expectedState",missing.length()==0?"directory":"absent").put("anchorPath",anchor).put("anchorIdentity",anchorIdentity).put("missingPaths",missing);
        JSONObject row=new JSONObject().put("path",target).put("action","mkdir").put("resourceKind","directory").put("directoryContract",CONTRACT).put("directoryPlan",descriptor).put("directoryPin",ProjectSources.digest(descriptor));JSONArray rows=new JSONArray().put(row);preflight(root,rows,current);return rows;
    }
    public static JSONObject descriptor(JSONArray rows)throws Exception{
        if(rows.length()!=1)throw new SecurityException("目录创建须独占一次原补丁，不混合文件修改");JSONObject row=rows.getJSONObject(0);if(!matches(row)||!keys(row).equals(Set.of("path","action","resourceKind","directoryContract","directoryPlan","directoryPin"))||!"mkdir".equals(row.optString("action"))||!"directory".equals(row.optString("resourceKind")))throw new SecurityException("原目录动作类型/字段不完整");
        JSONObject plan=row.getJSONObject("directoryPlan");if(!keys(plan).equals(Set.of("path","createParents","expectedState","anchorPath","anchorIdentity","missingPaths"))||!(plan.opt("createParents")instanceof Boolean)||!ProjectSources.digest(plan).equals(row.getString("directoryPin")))throw new SecurityException("原目录pin已变化");String target=path(plan.getString("path")),anchor=plan.getString("anchorPath");if(!target.equals(row.getString("path"))||!anchor.isEmpty()&&!path(anchor).equals(anchor)||!plan.getString("anchorIdentity").matches("[a-f0-9]{64}"))throw new SecurityException("目录身份不准确");
        JSONArray missing=plan.getJSONArray("missingPaths");if(missing.length()==0){if(!"directory".equals(plan.optString("expectedState"))||!target.equals(anchor))throw new SecurityException("既有目录声明不完整");}
        else{if(!"absent".equals(plan.optString("expectedState"))||!plan.getBoolean("createParents")&&missing.length()!=1||missing.length()>MAX_DEPTH)throw new SecurityException("目录递归语义不准确");String previous=anchor;for(int i=0;i<missing.length();i++){String next=path(missing.getString(i)),parent=next.contains("/")?next.substring(0,next.lastIndexOf('/')):"";if(!parent.equals(previous))throw new SecurityException("缺失目录不是准确连续父子路径");previous=next;}if(!previous.equals(target))throw new SecurityException("目录末项并非本次target");}return plan;
    }
    public static void requirePlan(JSONObject original,JSONObject step,JSONArray rows)throws Exception{JSONObject directory=descriptor(rows),payload=step.getJSONObject("payload");if(!"patch".equals(original.optString("intent"))||!"patchFiles".equals(step.optString("localCommand"))||!original.getString("checkoutId").equals(payload.optString("checkoutId"))||!original.getString("sourceDigest").equals(payload.optString("expectedSourceDigest")))throw new SecurityException("目录动作不在原准确patch方案");JSONArray manifest=original.getJSONArray("sourceManifest"),missing=directory.getJSONArray("missingPaths");for(int i=0;i<manifest.length();i++){String file=manifest.getJSONObject(i).getString("path");if(file.equals(directory.getString("path")))throw new SecurityException("目录目标是原文件");for(int m=0;m<missing.length();m++)if(file.startsWith(missing.getString(m)+"/"))throw new SecurityException("缺失目录声明与原文件清单冲突");}}
    public static void preflight(File root,JSONArray rows,ProjectFileQueries.Current current)throws Exception{JSONObject plan=descriptor(rows);if(!plan.getString("anchorIdentity").equals(identity(root,plan.getString("anchorPath"),current)))throw new SecurityException("原目录/已有父目录身份已变化，请重新审阅");JSONArray missing=plan.getJSONArray("missingPaths");for(int i=0;i<missing.length();i++)if(!"absent".equals(identity(root,missing.getString(i),current)))throw new SecurityException("拟创建目录已变化，未将新路径冒原批准");current.check();}
    public static JSONObject execute(File root,JSONArray rows,ProjectFileQueries.Current current)throws Exception{
        JSONObject plan=descriptor(rows),row=new JSONObject().put("path",plan.getString("path")).put("action","mkdir").put("resourceKind","directory").put("directoryPin",rows.getJSONObject(0).getString("directoryPin")).put("state","pending").put("commitAttempted",false).put("createdPaths",new JSONArray());JSONArray receipts=new JSONArray().put(row),created=row.getJSONArray("createdPaths"),missing=plan.getJSONArray("missingPaths");boolean entered=false;
        try{preflight(root,rows,current);if(missing.length()==0){String existing=identity(root,plan.getString("path"),current);if(!existing.equals(plan.getString("anchorIdentity")))throw new SecurityException("原既有目录在核对期间变化");row.put("state","applied").put("directoryOutcome","already_exists").put("actualDirectoryIdentity",existing);return result("completed",true,false,receipts,false,"原准确目录已存在；没有调用mkdir或覆盖任何内容");}
            String parent=plan.getString("anchorPath"),parentIdentity=plan.getString("anchorIdentity");for(int i=0;i<missing.length();i++){String next=missing.getString(i);if(!parentIdentity.equals(identity(root,parent,current))||!"absent".equals(identity(root,next,current)))throw new SecurityException("目录父子状态在派发前变化");Path target=resolve(root,next).toPath();current.check();entered=true;row.put("commitAttempted",true);Files.createDirectory(target);String actual=identity(root,next,()->{});if("absent".equals(actual))throw new IllegalStateException("mkdir后未观察到普通目录");created.put(new JSONObject().put("path",next).put("identity",actual).put("state","created"));parent=next;parentIdentity=actual;}
            String settled=identity(root,plan.getString("path"),()->{});if(!parentIdentity.equals(settled))throw new SecurityException("mkdir后目录身份未收敛");row.put("state","applied").put("directoryOutcome","created").put("actualDirectoryIdentity",settled);return result("completed",true,true,receipts,false,"已逐个调用Files.createDirectory并核对本次列出的目录；只改工作副本，不写正式版本库/恢复运行权限");
        }catch(Exception failure){row.put("state",entered?"unknown":"failed").put("directoryOutcome",entered?"unknown":"not_created");return result(entered?"unknown":"failed",!entered,entered,receipts,entered?JSONObject.NULL:false,entered?"目录创建已进入，未收敛完整回执；保留已观察createdPaths与原操作unknown，不自动回滚、重放或rmdir":"目录预检/授权未通过，未进入mkdir；重新核对目录pin和原权限");}
    }
    private static JSONObject result(String status,boolean receipt,boolean attempted,JSONArray rows,Object partial,String message)throws Exception{return new JSONObject().put("status",status).put("exitCode",status.equals("unknown")?JSONObject.NULL:status.equals("completed")?0:1).put("receiptReceived",receipt).put("files",rows).put("appliedFiles",0).put("allFilesApplied",status.equals("completed")).put("partialEffects",partial).put("fileCommitAttempted",attempted).put("crossFileAtomic",false).put("replayAllowed",false).put("message",message);}
}
